package br.com.cineo;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Account/viewer scoped snapshots. Auth, staff, exports and mutations never enter this cache. */
class FastCache {
 final MainActivity a;final LinkedHashMap<String,Entry> memory=new LinkedHashMap<>(32,.75f,true);static final long FRESH=30000,MAX=86400000;long epoch=0;boolean force=false;
 static class Entry{final String json;final long at;Entry(String value,long time){json=value;at=time;}JSONObject value()throws Exception{return new JSONObject(json);}}
 FastCache(MainActivity activity){a=activity;}
 String scope(){return a.uid+"|"+a.viewerId+"|"+a.viewerToken.hashCode()+"|"+a.viewerKids+"|"+a.viewerMaxRating;}
 boolean permitted(String path){String p=path.split("\\?",2)[0];return p.matches("/(v9/(start|catalog)|catalog|saved|mine|shows/\\d+(/episodes|/save)?|v4/(profile|home|progress|following|follow|creator/[a-f0-9-]+|show/\\d+/extras)|v7/home|v6/(preferences|categories|history|lists|list/\\d+|rating)|v8/(home|bootstrap|preferences|library|recommendations|search|bookmarks|calendar|inbox|surveys|news|studio|drafts|show/\\d+/(info|gaps|materials|proposals|revisions)|polls/\\d+))");}
 boolean disk(String path){return !a.viewerKids&&!path.matches(".*(/episodes|/materials|/proposals|/revisions|/drafts|/mine|/studio|/inbox|/bootstrap|/profile|/save)(\\?.*)?$");}
 File folder(){File dir=new File(a.getFilesDir(),"snapshots-v9");dir.mkdirs();return dir;}
 String hash(String input)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)))out.append(String.format(Locale.US,"%02x",b&255));return out.toString();}
 synchronized Entry get(String scope,String path){if(!permitted(path)||scope.startsWith("|"))return null;String key=scope+"|"+path;Entry found=memory.get(key);try{if(found==null&&disk(path)){File file=new File(folder(),hash(key));if(file.isFile()&&file.length()<1600000){if(file.lastModified()==1&&!feed(path))return null;JSONObject row=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));found=new Entry(row.getString("json"),file.lastModified()==1?Math.min(row.getLong("at"),System.currentTimeMillis()-FRESH-1):row.getLong("at"));memory.put(key,found);}}if(found==null)return null;long age=System.currentTimeMillis()-found.at;if(age<0||age>(path.contains("/episodes")?60000:MAX))return null;return found;}catch(Exception ignored){return null;}}
 synchronized void put(String scope,String path,JSONObject value,long expectedEpoch){if(expectedEpoch!=epoch||!permitted(path)||scope.startsWith("|"))return;String json=value.toString();if(json.length()>1200000||value.has("token")||value.has("refresh_token"))return;String key=scope+"|"+path;Entry entry=new Entry(json,System.currentTimeMillis());memory.put(key,entry);while(memory.size()>64)memory.remove(memory.keySet().iterator().next());if(disk(path))try{File target=new File(folder(),hash(key)),temp=new File(target+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(new JSONObject().put("json",json).put("at",entry.at).toString().getBytes(StandardCharsets.UTF_8));}if(!temp.renameTo(target))temp.delete();prune();}catch(Exception ignored){}}
 synchronized void prune(){File[] files=folder().listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long bytes=0;for(int i=0;i<files.length;i++){bytes+=files[i].length();if(i>=40||bytes>8000000)files[i].delete();}}
 boolean feed(String path){return path.startsWith("/v9/start")||path.startsWith("/v9/catalog")||path.equals("/catalog")||path.equals("/v4/home")||path.equals("/v7/home");}
 synchronized void changed(){epoch++;long stale=System.currentTimeMillis()-FRESH-1;Iterator<Map.Entry<String,Entry>> iterator=memory.entrySet().iterator();while(iterator.hasNext()){Map.Entry<String,Entry> entry=iterator.next();String path=entry.getKey().substring(entry.getKey().lastIndexOf('|')+1);if(feed(path))entry.setValue(new Entry(entry.getValue().json,Math.min(entry.getValue().at,stale)));else iterator.remove();}File[] files=folder().listFiles();if(files!=null)for(File file:files)file.setLastModified(1);}
 synchronized void invalidate(){epoch++;memory.clear();File[] files=folder().listFiles();if(files!=null)for(File file:files)file.delete();}
 synchronized int count(){return memory.size();}
}
